def audits_from_this_week(apps, schema_editor):
    # Weekly audits are due from the deploy week on; earlier weeks never count as missed.
    today = timezone.localdate()
    apps.get_model('revenue', 'RevenueSettings').objects.update(audits_from=today - timedelta(days=today.weekday()))


